def clearing_detail(p, code, other):
    """Describe why a press-dependent finding would NOT be raised on `other` press."""
    pr = presses[other]
    min_dpi = int(pr["min_effective_dpi"]); max_tac = int(pr["max_tac_pct"]); max_spot = int(pr["max_spot_colors"])
    if code == "DPI_TOO_LOW":
        return f"effective {p['eff_dpi']} dpi \u2265 {min_dpi} dpi floor on {other}"
    if code == "INK_OVER_LIMIT":
        return f"TAC {p['ink_tac']}% \u2264 {max_tac}% cap on {other}"
    if code == "SPOT_UNSUPPORTED":
        return f"{p['spot']} spot colour(s) \u2264 {max_spot} supported on {other}"
    return code

for p, op, cleared in partial_clear:
    det = "; ".join(clearing_detail(p, c, op) for c in cleared)
    A(f"| {p['page_id']} | {p['section_id']} / {p['press_id']} → {op} | {det} |")

